B.ZQ=new A.bq(B.b3,B.Nj)
B.Sh=new A.fu("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.Nq=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
