B.Pk=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.a_2=new A.bq(B.ba,B.Pk)
B.Nt=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
