B.No=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.ZL=new A.bq(B.ba,B.No)
B.N5=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.a_f=new A.bq(B.aA,B.N5)
B.M5=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
