B.Ny=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.ZU=new A.bq(B.ba,B.Ny)
B.Pw=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.ZV=new A.bq(B.aA,B.Pw)
